xaxis(-2,5,Ticks(" ",1.0,begin=false,end=false,NoZero,Size=3),Arrows(4));
yaxis(-2,5,Ticks(" ",1.0,begin=false,end=false,NoZero,Size=3),Arrows(4));

dot("$B$",(4,1),SE);
dot("$C$",(4,4),N);
dot("$C'$",(1,1),W);
